"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["1409"],{7592(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>d,frontMatter:()=>i,contentTitle:()=>s,toc:()=>l,assets:()=>c});var o=JSON.parse('{"id":"reference/admin/howtos/renewals","title":"How to Create a Renewal Quote","description":"almsc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/admin/howtos/renewals.md","sourceDirName":"reference/admin/howtos","slug":"/reference/admin/howtos/renewals","permalink":"/personal-av-docs/docs/reference/admin/howtos/renewals","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/admin/howtos/renewals.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to Create a Renewal Quote","sidebar_label":"How to Create a Renewal Quote","sidebar_position":99,"edition":"almsc","source":"https://doc.airvantage.net/almsc/reference/admin/howtos/renewals","format":"md"}}'),a=n(4848),r=n(8453);let i={title:"How to Create a Renewal Quote",sidebar_label:"How to Create a Renewal Quote",sidebar_position:99,edition:"almsc",source:"https://doc.airvantage.net/almsc/reference/admin/howtos/renewals",format:"md"},s,c={},l=[];function u(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"almsc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/almsc/reference/admin/howtos/renewals",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsxs)(t.p,{children:["How to Create a Renewal Quote\nIf you are the administrator for an ALMSC pre-paid account, you can generate renewal quotes for your AirLink routers. Instead of waiting for quotes to come from Semtech\u2019s Renewals team, Renewals self-service lets you generate reference quotes for the devices and pre-paid offers in your account, so you can plan your budget accordingly.\nNote that your profile must have Renewal quote read/write permission to generate a renewal quote.\nThe\nRenewal Quotations\ntool is for reference and budgeting purposes only and does not produce an official quote. For procurement purposes, please provide this document to your Semtech authorized reseller of choice for an official quote and pricing. Semtech does not sell directly to customers.\nThe Renewal Quotations tool\nincludes\ndevices whose service has expired, and whose service is due for renewal in the next 12 months.\nThe Renewal Quotations tool\ndoes not include\ndevices that are not activated (in the\nInventory\nstate) or not due for renewal in the next 12 months.\nCreating a Quote\nTo create a quote:\nFrom\nAdministration > Renewals\n, click\nCreate Quote\n.\nSelect a service for the devices that are due for renewal in the next 12 months.\nThe available services depend on the devices and offers currently in your account. In this example, the account has RX55 and XR90 routers due for renewal. The page shows which offers are available for each type of device.\nSelect the duration of the service (1 Year, 3 Years or 5 Years).\nThe quote in progress appears under\nQuote Preview\n.\nSelect the service co-termination date. This applies a common end date for the renewed devices and service(s). See\nAbout Co-Termination Dates\nbelow.\nClick\nCreate Quote\n.\nThe Renewals home page appears, and your new quote appears in the list.\nNote that quotes have an expiry date (seen in the\nQuote expires\ncolumn), which is set to the end of the month after the quote\u2019s creation date.\nAbout Co-Termination Dates\nThe earliest co-termination date available is based on the month following the quote creation date plus the selected service duration. The last co-termination date extends one year past the earliest available date. You can select any month in that range. The system will pro-rate any totals for devices that will have service periods of less than or greater than the selected service duration.\nFor example,\nDevice 1\nin your account expires on\nSeptember 1, 2027\nand\nDevice 2\nexpires on\nDecember 1, 2027\n. If you create a quote in December 2026 and select a service duration of one year, the available co-termination dates will start at January 2028.\nThe co-termination date range is calculated as follows:\nStart = the month after the quote date plus the service duration = January 2028\nEnd = 12 months after the start (inclusive) = December 2028\nYou can select any co-termination date from January 2028 to December 2028. If you select a co-termination date of August 2028, both devices will terminate at the end of August 31, 2028:\nDevice 1\n(expiring September 1, 2027, reporting to ALMS through 23:59h August 31, 2027) will have one year of service through August 31, 2028.\nDevice 2\n(expiring December 1, 2027, reporting to ALMS through 23:59h November 30, 2027) will have nine months of service through August 31, 2028, and its total price will be pro-rated accordingly.\nAll co-termination dates resolve to the last calendar day of the selected month (for example, February\n28\n\u2044\n29\nor June 30). Any mid-month expiry dates in your account are always rounded up to month-end.\nRenewal Quotation Actions\nIn the\nActions\ncolumn, you can:\nshare a link to the quote details. The link opens the quote details page. If the quote has not expired, you can click\nRevise Quote\non the quote details page to edit the quote and save it as a new quote.\nexport the quote to an .xls file\ndownload the quotation as a PDF\nrevise the quote\nTo revise a quote:\nIn the\nActions\ncolumn for the quote you want to revise, click\n(Revise quote).\n-or-\nClick the Quote ID in the table and then click\nRevise Quote\n.\nUpdate the quote to pick a different service, change the duration, and/or select a different co-termination date as described in\nCreating a Quote\nabove.\nClick\nRevise Quote\n. The revised quote will be saved as a new quote.\nWhat\u2019s Next?\nAfter generating the reference quote, you can forward it to your Semtech authorized reseller for an official quote to procure from. Semtech does not sell direct to end customers.\nIf you have any other questions or concerns, please contact\n",(0,a.jsx)(t.a,{href:"mailto:renewals-SWI@semtech.com",children:"renewals-SWI@semtech.com"}),"\n."]})]})}function d(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>s});var o=n(6540);let a={},r=o.createContext(a);function i(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);